<?php declare(strict_types=1);namespace App\Models;use App\Core\DB;final class License extends Model{protected static string $table='licenses';protected static array $json=['features'];public const STATUSES=['active','suspended','expired','revoked'];public static function findByKey(string $p):?array{return static::findBy('license_key',$p);}public static function forUser(int $X):array{return static::castAll(static::query()->where('user_id',$X)->orderBy('created_at','DESC')->get());}public static function withPlan(int $n):?array{$O=DB::fetch('SELECT l.*, p.slug AS plan_slug, p.name AS plan_name, u.email AS user_email, u.name AS user_name, u.company AS user_company FROM {{licenses}} l JOIN {{plans}} p ON p.id = l.plan_id JOIN {{users}} u ON u.id = l.user_id WHERE l.id = ?',[$n]);if(!$O){return null;}$O=static::cast($O);$O['plan_name']=json_decode((string)$O['plan_name'],true)?:[];return $O;}public static function activations(int $M,bool $P=false):array{$j=DB::from('activations')->where('license_id',$M)->orderBy('activated_at','DESC');if($P){$j->where('revoked_at',null);}return $j->get();}public static function activeActivationCount(int $W):int{return DB::from('activations')->where('license_id',$W)->where('revoked_at',null)->count();}public static function events(int $g,int $j=50):array{return DB::from('license_events')->where('license_id',$g)->orderBy('id','DESC')->limit($j)->get();}public static function logEvent(int $e,string $i,array $z=[],?string $a=null):void{DB::insert('license_events',['license_id'=>$e,'action'=>$i,'details'=>$z,'ip'=>$a,'created_at'=>now()]);}public static function isExpired(array $a):bool{return strtotime((string)$a['expires_at'])<time();}public static function effectiveStatus(array $C):string{if($C['status']==='active'&&static::isExpired($C)){return'expired';}return $C['status'];}}